# Workflow transaction with rollback: Saga Pattern with Compensating Actions
steps_done = []
def step(name, undo):
    print("run:", name); steps_done.append((name, undo))
def rollback():
    for name, undo in reversed(steps_done):
        print("rollback:", name); undo()
step("reserve-inventory", lambda: print("  released reservation"))
step("charge-card", lambda: print("  refunded charge"))
try:
    raise RuntimeError("payment gateway timeout")
except RuntimeError as e:
    print("failed:", e); rollback()
print("atomicity:", "compensated atomicity", "- no partial effects remain")

